return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_03]],["connectPoint"]=0,["name"]=[[四方小院]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_01]],["dsc"]=[[院中植古松，地板以黑白石子铺成，形成一个巨大的太极。中庭的石桌上放有一把拂尘，不知从何处吹来的落叶落于其上。位处小院，隐约可闻远处钟鼓之声。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[四方小院(fb627_02)]],["canLeave"]=1,["id"]=[[fb627_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[太一居]],["permission"]=0,["left"]=[[fb627_02]],["fullName"]=[[太一居(fb627_03)]],["enterable"]=1,["dsc"]=[[道者，至精也，不可为形，不可为名，强为之名，谓之太一。此居门前两盆青松，内置松鹤云山原木屏风，木桌两张。推窗可见远山云雾，缥缈清幽。]],["down"]=[[fb627_09]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc01]],["unit1"]=[[npc06f]],["canLeave"]=1,["id"]=[[fb627_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[卧房]],["permission"]=0,["enterable"]=1,["dsc"]=[[一间素净的卧房，房中一张床榻上铺有蓝布被褥，整齐叠放着一件道袍，墙壁上悬挂一把长剑，几本道书放于门口的木桌上，除此之外再无其他。]],["down"]=[[fb627_02]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[卧房(fb627_01)]],["canLeave"]=1,["id"]=[[fb627_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_07]],["connectPoint"]=0,["name"]=[[茶园]],["permission"]=0,["left"]=[[fb627_05]],["enterable"]=1,["dsc"]=[[武当山茶园，植有一望无际的茶树，中间是一个巨大的茶棚，茶桌数十张，可容百人。每至采茶之时，门中弟子都会背着箩筐到此煎茶品茗，论道清修。]],["fullName"]=[[茶园(fb627_06)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10h]],["unit2"]=[[npc09h]],["unit1"]=[[npc07h]],["canLeave"]=1,["id"]=[[fb627_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[茶庄]],["permission"]=0,["left"]=[[fb627_06]],["enterable"]=1,["dsc"]=[[武当山下的茶庄，隶属武当派。庄内多竹制摆设，乃至桌椅床榻。每每晨曦之刻，在此总能听到武当道乐。]],["fullName"]=[[茶庄(fb627_07)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10i]],["unit2"]=[[npc09i]],["unit1"]=[[npc07i]],["canLeave"]=1,["id"]=[[fb627_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[山路]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_32]],["dsc"]=[[这是一条登山的小路，路的左右各有一条大铁链，像两条长蛇向山上山下蜿蜒爬去。满眼是乔木夹道，如行于绿幕中。]],["down"]=[[fb627_11]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[山路(fb627_04)]],["canLeave"]=1,["id"]=[[fb627_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_06]],["connectPoint"]=0,["name"]=[[隐仙岩]],["permission"]=0,["enterable"]=1,["dsc"]=[[隐仙岩为武当山三十六岩中的一座大型岩洞，传闻古时诸多高人在此悟道。洞内有多座石殿，正殿设两尊石刻像，为道家“太阳星君”与“太阴星君”。]],["down"]=[[fb627_15]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[隐仙岩(fb627_05)]],["canLeave"]=1,["id"]=[[fb627_05]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb627_19]],["connectPoint"]=0,["name"]=[[太乙玄清楼]],["permission"]=0,["rightDown"]=[[fb627_29]],["fullName"]=[[太乙玄清楼(fb627_24)]],["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[楼高三层，每层长梯共七七四十九阶。楼内中空，自上而下可见楼内正中石板所铺的八卦图。八角墙壁上各悬挂一把长剑，推窗可观武当山海云岚，蔚为壮观。]],["down"]=[[fb627_28]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc03]],["canLeave"]=1,["id"]=[[fb627_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[药房]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_20]],["dsc"]=[[武当药房，四面墙壁上皆是药橱，共数百种草药，每个小柜上则用木牌雕刻着所存放草药的药名。药房后院中一排药壶正在煎煮，散发着浓郁的中草药味。]],["fullName"]=[[药房(fb627_25)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc06d]],["unit1"]=[[npc06c]],["canLeave"]=1,["id"]=[[fb627_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_09]],["connectPoint"]=0,["name"]=[[靖庐]],["permission"]=0,["enterable"]=1,["dsc"]=[[靖庐，也称靖室或静庐，乃是修道之地。室中清虚，素净非常，除敬神的香炉、香案、上章进表的章案和书刀四件神器外，不多放杂物。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[靖庐(fb627_08)]],["canLeave"]=1,["id"]=[[fb627_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_10]],["connectPoint"]=0,["name"]=[[凌虚岩]],["permission"]=0,["left"]=[[fb627_08]],["fullName"]=[[凌虚岩(fb627_09)]],["enterable"]=1,["up"]=[[fb627_03]],["dsc"]=[[凌虚岩四周满目葱翠，极为隐蔽，是武当门人悟道修行的绝佳之地。岩上建石殿，供奉元始天尊等塑像。岩下泉水流淌，声似击鼓雷鸣，又似浪潮翻涌。]],["down"]=[[fb627_18]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10b]],["unit2"]=[[npc09b]],["unit1"]=[[npc07b]],["canLeave"]=1,["id"]=[[fb627_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[丹房]],["permission"]=0,["left"]=[[fb627_19]],["fullName"]=[[丹房(fb627_20)]],["enterable"]=1,["dsc"]=[[一间丹房，中间巨大的八卦图上放置一顶巨大的丹炉，炉内火烧得正旺，旁侧的木架上放置多种不知名的草药和精致的瓷瓶。]],["down"]=[[fb627_25]],["visible"]=1,["unit4"]=[[npc10f]],["dirIndex"]=0,["unit3"]=[[npc09f]],["unit2"]=[[npc07f]],["unit1"]=[[npc06e]],["canLeave"]=1,["id"]=[[fb627_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_22]],["connectPoint"]=0,["name"]=[[两仪湖]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_14]],["dsc"]=[[湖中有岛，岛上建有水榭雅居。居内设钟鼓萧乐，乃是因为武当道乐天下闻名，每至晨曦暮刻，便有道士奏响。岛与两岸以水栈道相勾连，自山顶俯视，此湖形如太极。]],["down"]=[[fb627_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[两仪湖(fb627_21)]],["canLeave"]=1,["id"]=[[fb627_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[逍遥谷]],["permission"]=0,["left"]=[[fb627_21]],["enterable"]=1,["dsc"]=[[谷内多百兽，或因深处道家之所，显有猛禽。且谷中清溪长流，汇聚于两仪湖。林中寂静，常有武当门人到此寻一块僻静之处，坐于岩上参悟道法。]],["fullName"]=[[逍遥谷(fb627_22)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06a]],["canLeave"]=1,["id"]=[[fb627_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[卧房]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_17]],["dsc"]=[[一间素净的卧房，房中一张床榻上铺有蓝布被褥，整齐叠放着一件道袍，墙壁上悬挂一把长剑，几本道书放于门口的木桌上，除此之外再无其他。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[卧房(fb627_23)]],["canLeave"]=1,["id"]=[[fb627_23]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[四方小院]],["permission"]=0,["left"]=[[fb627_27]],["enterable"]=1,["up"]=[[fb627_24]],["dsc"]=[[院中植古松，地板以黑白石子铺成，形成一个巨大的太极。中庭的石桌上放有一把拂尘，不知从何处吹来的落叶落于其上。位处小院，隐约可闻远处钟鼓之声。]],["fullName"]=[[四方小院(fb627_28)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06b]],["canLeave"]=1,["id"]=[[fb627_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_30]],["connectPoint"]=0,["name"]=[[二楼]],["permission"]=0,["fullName"]=[[二楼(fb627_29)]],["enterable"]=1,["dsc"]=[[太乙玄清楼的二楼，墙壁上满刻《道德经》，传闻乃是出自名家之手，后人瞻仰，时常临摹，故楼内设桌案多张，以供弟子使用。]],["down"]=[[fb627_31]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb627_24]],["canLeave"]=1,["id"]=[[fb627_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_28]],["connectPoint"]=0,["name"]=[[无为崖]],["permission"]=0,["enterable"]=1,["dsc"]=[[无为有处有还无，此崖由此而名。崖下深渊云雾缭绕而不见其底，边缘一棵瘦弱的小树根部显露，似倒未倒，向死而生。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[无为崖(fb627_27)]],["canLeave"]=1,["id"]=[[fb627_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[试剑坪]],["permission"]=0,["enterable"]=1,["up"]=[[fb627_21]],["dsc"]=[[一块巨大的岩石坪，四周有不少刀剑的划痕，乃是因弟子们练剑之时剑气所刻。自此远望，可见青山翠郁，云烟缭绕。]],["fullName"]=[[试剑坪(fb627_26)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10a]],["unit2"]=[[npc09a]],["unit1"]=[[npc07a]],["canLeave"]=1,["id"]=[[fb627_26]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_16]],["connectPoint"]=0,["name"]=[[桃园]],["permission"]=0,["left"]=[[fb627_14]],["enterable"]=1,["up"]=[[fb627_05]],["dsc"]=[[据说园内种有数百棵桃树，每隔数百步放一张石桌，桌上清茶鲜果，阵阵花香飘来，让人不禁想在此休憩片刻。]],["fullName"]=[[桃园(fb627_15)]],["visible"]=1,["unit4"]=[[npc10e]],["dirIndex"]=0,["unit3"]=[[npc09e]],["unit2"]=[[npc07e]],["unit1"]=[[npc06g]],["canLeave"]=1,["id"]=[[fb627_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb627_15]],["connectPoint"]=0,["name"]=[[小路]],["permission"]=0,["left"]=[[fb627_13]],["enterable"]=1,["dsc"]=[[眼前豁然开朗，你轻松地走在桃园边的小路上。两边是桃树林，树上盛开着粉红的桃花，红云一片，望不到边。]],["down"]=[[fb627_21]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[小路(fb627_14)]],["canLeave"]=1,["id"]=[[fb627_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[四方小院]],["permission"]=0,["left"]=[[fb627_16]],["fullName"]=[[四方小院(fb627_17)]],["enterable"]=1,["dsc"]=[[院中植古松，地板以黑白石子铺成，形成一个巨大的太极。中庭的石桌上放有一把拂尘，不知从何处吹来的落叶落于其上。位处小院，隐约可闻远处钟鼓之声。]],["down"]=[[fb627_23